import fs from 'fs';
import path from 'path';
import { isPathStrictlyInsideRoot } from '../utils/pathContainment';

const STATIC_HTML_EXTENSIONS = new Set(['.html', '.htm']);
const DEFAULT_STATIC_ENTRY = 'index.html';

export type StaticProjectTarget = {
  projectPath: string;
  entryPath: string;
  htmlEntryFiles: string[];
};

type ResolveStaticProjectTargetInput = {
  targetPath: string;
  entryPath?: string;
};

export const isStaticHtmlFilePath = (filePath: string): boolean =>
  STATIC_HTML_EXTENSIONS.has(path.extname(filePath).toLowerCase());

export const listStaticHtmlEntryFiles = (projectPath: string): string[] => {
  if (!fs.existsSync(projectPath)) return [];
  const stats = fs.statSync(projectPath);
  if (!stats.isDirectory()) return [];

  return fs
    .readdirSync(projectPath, { withFileTypes: true })
    .filter((entry) => entry.isFile() && isStaticHtmlFilePath(entry.name))
    .map((entry) => entry.name)
    .sort((left, right) => left.localeCompare(right));
};

const normalizeEntryPath = (entryPath: string): string =>
  entryPath.split(path.sep).join('/');

const resolveEntryPath = (projectPath: string, entryPath: string): string => {
  const resolvedProjectPath = path.resolve(projectPath);
  const resolvedEntryPath = path.isAbsolute(entryPath)
    ? path.resolve(entryPath)
    : path.resolve(resolvedProjectPath, entryPath);
  if (!isPathStrictlyInsideRoot(resolvedProjectPath, resolvedEntryPath)) {
    throw new Error(`Static entry must be inside projectPath: ${entryPath}`);
  }

  return normalizeEntryPath(
    path.relative(resolvedProjectPath, resolvedEntryPath),
  );
};

export const resolveStaticProjectTarget = ({
  targetPath,
  entryPath,
}: ResolveStaticProjectTargetInput): StaticProjectTarget => {
  const resolvedTargetPath = path.resolve(targetPath);
  if (!fs.existsSync(resolvedTargetPath)) {
    throw new Error(`Project path does not exist: ${resolvedTargetPath}`);
  }

  const targetStats = fs.statSync(resolvedTargetPath);
  if (targetStats.isFile()) {
    if (!isStaticHtmlFilePath(resolvedTargetPath)) {
      throw new Error(
        `Static project file must be an HTML file: ${targetPath}`,
      );
    }
    const projectPath = path.dirname(resolvedTargetPath);
    return {
      projectPath,
      entryPath: path.basename(resolvedTargetPath),
      htmlEntryFiles: listStaticHtmlEntryFiles(projectPath),
    };
  }

  if (!targetStats.isDirectory()) {
    throw new Error(
      `Project path must be a directory or HTML file: ${targetPath}`,
    );
  }

  const htmlEntryFiles = listStaticHtmlEntryFiles(resolvedTargetPath);
  if (entryPath) {
    return {
      projectPath: resolvedTargetPath,
      entryPath: resolveEntryPath(resolvedTargetPath, entryPath),
      htmlEntryFiles,
    };
  }

  if (htmlEntryFiles.includes(DEFAULT_STATIC_ENTRY)) {
    return {
      projectPath: resolvedTargetPath,
      entryPath: DEFAULT_STATIC_ENTRY,
      htmlEntryFiles,
    };
  }

  if (htmlEntryFiles.length === 1) {
    return {
      projectPath: resolvedTargetPath,
      entryPath: htmlEntryFiles[0],
      htmlEntryFiles,
    };
  }

  return {
    projectPath: resolvedTargetPath,
    entryPath: DEFAULT_STATIC_ENTRY,
    htmlEntryFiles,
  };
};
